#include <bits/stdc++.h>
using namespace std; using i128=__int128_t; using u64=unsigned long long;
long long eg(long long a,long long b,long long&x,long long&y){if(!b){x=1;y=0;return a;}long long x1,y1,g=eg(b,a%b,x1,y1);x=y1;y=x1-y1*(a/b);return g;}
long long invmod(long long a,long long m){long long x,y;if(eg(a,m,x,y)!=1)return -1;x%=m;if(x<0)x+=m;return x;}
bool crt_cons(const vector<pair<long long,long long>>&c){for(int i=0;i<(int)c.size();i++)for(int j=0;j<i;j++){long long g=gcd(c[i].second,c[j].second);if((c[i].first-c[j].first)%g)return false;}return true;}
vector<pair<long long,int>> factor(long long n,const vector<int>&spf){vector<pair<long long,int>> f;while(n>1){long long p= n<(long long)spf.size()?spf[n]:0;if(!p){ // fallback trial
 p=2;while(p*p<=n&&n%p)p++;if(p*p>n)p=n;
 }int e=0;while(n%p==0){n/=p;e++;}f.push_back({p,e});}return f;}
void gen_divs(const vector<pair<long long,int>>&f,int i,long long cur,vector<long long>&out){if(i==(int)f.size()){out.push_back(cur);return;}auto[p,e]=f[i];for(int j=0;j<=e;j++){gen_divs(f,i+1,cur,out);if(j<e){if((i128)cur*p>LLONG_MAX)return;cur*=p;}}}
int main(int argc,char**argv){int Z=argc>1?atoi(argv[1]):1000;int maxv=Z*Z+Z+10;vector<int>spf(maxv);for(int i=2;i<maxv;i++)if(!spf[i]){spf[i]=i;if((long long)i*i<maxv)for(long long j=1LL*i*i;j<maxv;j+=i)if(!spf[j])spf[j]=i;}long long pairs=0,divs=0,stageD=0,stageC=0,stageCong=0,hits=0,maxA=0,maxAD=0;for(int z=2;z<=Z;z++)for(int w=1;w<z;w++){pairs++; long long f1=z+w,f2=1LL*z*z-z*w+1LL*w*w; auto a=factor(f1,spf),b=factor(f2,spf); map<long long,int> mp;for(auto x:a)mp[x.first]+=x.second;for(auto x:b)mp[x.first]+=x.second;vector<pair<long long,int>> ff(mp.begin(),mp.end());vector<long long> ds;gen_divs(ff,0,1,ds);sort(ds.begin(),ds.end());ds.erase(unique(ds.begin(),ds.end()),ds.end());for(long long A:ds){if(A<=5LL*z)continue;divs++;maxA=max(maxA,A);if(gcd(A,z)!=1||gcd(A,w)!=1)continue;long long C=2*A-z,D=2*A-w;if(C<=0||D<=0)continue;i128 N1=(i128)C*C-(i128)A*A;if(N1%D)continue;long long k=(long long)(N1/D),y=k-A;if(!(0<y&&y<A))continue;stageD++;maxAD=max(maxAD,A);i128 G=(i128)(A+4LL*z)*(A+4LL*z)-(i128)(z-w)*(z-w);if(G%C)continue;stageC++;if(((i128)y*y+(i128)w*z)%A||((i128)y*w+(i128)z*z)%A)continue;stageCong++;
 long long p[5]={A,C,A,C,A},q[5]={A+z,3*(A+z),A+y,D,D}; if(gcd(p[1],q[1])!=1||gcd(p[2],q[2])!=1||gcd(p[3],q[3])!=1||gcd(p[4],q[4])!=1)continue;vector<pair<long long,long long>> con;int T[5]={0,0,2,4,3},S[5]={2,3,4,1,0};bool ok=true;for(int i=0;i<5;i++){int j=T[i];long long g=i==1?3:1;if(q[i]!=g*q[j]){ok=false;break;}long long iv=invmod(p[i],q[i]);if(iv<0){ok=false;break;}long long rr=(long long)((i128)g*p[j]%q[i]*iv%q[i]);if(gcd(rr,q[i])!=g){ok=false;break;}con.push_back({rr,q[i]});j=S[i];long long ci=q[i]-p[i],cj=q[j]-p[j],iv2=invmod(ci,p[i]);if(iv2<0){ok=false;break;}long long rs=(long long)((i128)cj%p[i]*iv2%p[i]);if(gcd(rs,p[i])!=1){ok=false;break;}con.push_back({rs,p[i]});}if(ok&&crt_cons(con)){cout<<"HIT A="<<A<<" z="<<z<<" w="<<w<<" y="<<y<<"\n";hits++;}}
 }
cerr<<"Z="<<Z<<" pairs="<<pairs<<" divisors="<<divs<<" stageD="<<stageD<<" stageC="<<stageC<<" stageCong="<<stageCong<<" hits="<<hits<<" maxA="<<maxA<<" maxAD="<<maxAD<<"\n";}
